import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"小畜","description":"周易正義 - 小畜","frontmatter":{"title":"小畜","description":"周易正義 - 小畜"},"headers":[],"relativePath":"classics/zhengyi/009.md","filePath":"classics/zhengyi/009.md"}'),l={name:"classics/zhengyi/009.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>風天小畜</p></blockquote><blockquote><p>卦辭：亨。密雲不雨，自我西郊。</p></blockquote><blockquote><p>彖曰：小畜，柔得位而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也；自我西郊，施未行也。</p></blockquote><h1 id="小畜" tabindex="-1">小畜 <a class="header-anchor" href="#小畜" aria-label="Permalink to “小畜”">​</a></h1><p>王弼：不能畜大，止健剛志，故行是以亨。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：但小有所畜，唯“畜”九三而已。初九、九二，猶剛健得行，是以剛志上得亨通，故云“小畜亨”也。若大畜、乾在於下，艮在於上，艮是陽卦，又能止物，能止此乾之剛健，所畜者大，故稱“大畜”。此卦則巽在於上，乾在於下，巽是陰，柔性，又和順，不能止畜在下之乾，唯能畜止九三，所畜狹小，故名“小畜”。</p><h3 id="密雲不雨-自我西郊。-​" tabindex="-1">密雲不雨，自我西郊。 ​ <a class="header-anchor" href="#密雲不雨-自我西郊。-​" aria-label="Permalink to “密雲不雨，自我西郊。 ​”">​</a></h3><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“密雲不雨”者，若陽之上升，陰能畜止，兩氣相薄則為雨也。今唯能畜止九三，其氣被畜，但為密雲，初九、九二，猶自上通，所以不能為雨也。“自我西郊”者，所聚密雲，由在我之西郊，去我既遠，潤澤不能行也，但聚在西郊而已。</p><h2 id="《彖》曰-小畜-柔得位而上下應之-曰-小畜-。-​" tabindex="-1">《彖》曰：小畜，柔得位而上下應之，曰“小畜”。 ​ <a class="header-anchor" href="#《彖》曰-小畜-柔得位而上下應之-曰-小畜-。-​" aria-label="Permalink to “《彖》曰：小畜，柔得位而上下應之，曰“小畜”。 ​”">​</a></h2><p>王弼：謂六四也，成卦之義，在此爻也。體無二陰，以分其應故上下應之也。既得其位，而上下應之，三不能陵，小畜之義。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“柔得位”，謂六四也。以陰居陰，故稱得位。此卦唯有一陰，上下諸陽皆來應之，故曰“小畜”。此釋小畜卦名也。言此卦之畜，六四唯畜其下九三，初九、九二猶不能擁畜，而云“上下應之”者，若細別而言，小畜之義，唯當畜止在下。三陽猶不能畜盡，但畜九三而已。若大判而言之，上下五陽總應六四，故云“上下應之”。其四雖應何妨，總不能畜止剛健也。</p><h3 id="健而巽-剛中而志行-乃亨。-密雲不雨-尚往也-自我西郊-施未行也。-​" tabindex="-1">健而巽，剛中而志行，乃亨。“密雲不雨”，尚往也；“自我西郊”，施未行也。 ​ <a class="header-anchor" href="#健而巽-剛中而志行-乃亨。-密雲不雨-尚往也-自我西郊-施未行也。-​" aria-label="Permalink to “健而巽，剛中而志行，乃亨。“密雲不雨”，尚往也；“自我西郊”，施未行也。 ​”">​</a></h3><p>王弼：小畜之勢，足作密雲，乃“自我西郊”，未足以為雨也。何由知未能為雨？夫能為雨者，陽上薄陰，陰能固之，然後烝而為雨。今不能制初九之“複道”，固九二之“牽復”，九三更以不能復為劣也。下方尚往，施豈得行？故密雲而不能為雨，尚往故也。何以明之？去陰能固之，然後乃雨乎。上九獨能固九三之路，故九三不可以進而“輿說輻”也。能固其路而安於上，故得“既雨既處”。若四、五皆能若上九之善畜，則能雨明矣。故舉一卦而論之，能為小畜密雲而已。陰苟不足以固陽，則雖復至盛，密雲自我西郊，故不能雨也。雨之未下，即施之未行也。《彖》至論一卦之體，故曰“密雲不雨”。《象》各言一爻之德，故曰“既雨既處”也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>“健而巽”至“施未行也”。</p><p>○正義曰：“健而巽，剛中而志行，乃亨”者，內既剛健而外逢柔順，剛發於外，不被摧抑，而志意得行。以此言之，故剛健之志，乃得亨通，此釋“亨”也。“密雲不雨，尚往”者，所以密雲不雨者，不能畜止諸陽，初九、九二，猶得上進，陰陽氣通，所以不雨，釋“密雲不雨”也。“自我西郊施未行”者，釋“自我西郊”之義。所以密雲不雨，從我西郊而積聚者，猶所施潤澤，未得流行周遍，故不覆國都，但遠聚西郊也。然雲在國都而不雨，亦是施未行也。必雲在西郊者，若在國都，雨雖未落，猶有覆蔭之施，不得雲“施未行”，今言在西郊，去施遠也。</p><p>○注“小畜之勢”至“既雨既處也”。</p><p>○正義曰：“九三更以不能復為劣”者，初九既得“複道”，九二可“牽”以獲“復”，皆得剛健上通，則是陰不能固陽，而九三劣弱，又不能自復，則是陽不薄陰，是以皆不雨也。且小畜之義，貴於上往，而九三不能自復，更為劣弱，故言“九三更不能復為劣”也。“能固其路而安於上”者，謂上九能閉固九三之道路，不被九三所陵，得安於上，所以“既雨既處”也，故舉一卦而論之。“能為小畜密雲而已”者，此明卦之與爻，其義別也。但卦總二象，明上體不能閉固下體，所以密雲不能為雨。爻則止明一爻之事，上九能固九三，所以上九而有雨也。所以卦與爻其義異也。諸卦多然。若《比卦》雲“比吉”，上六則雲“比之無首兇”也；《復卦》雲“復亨”，上六雲“迷復兇”也。此皆卦之與爻，義相違反，它皆仿此。</p><h3 id="《象》曰-風行天上-小畜。君子以懿文德。-​" tabindex="-1">《象》曰：風行天上，小畜。君子以懿文德。 ​ <a class="header-anchor" href="#《象》曰-風行天上-小畜。君子以懿文德。-​" aria-label="Permalink to “《象》曰：風行天上，小畜。君子以懿文德。 ​”">​</a></h3><p>王弼：未能行其施者，故可以懿文德而已。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“君子以懿文德”者，懿，美也。以於其時施末得行，喻君子之人但修美文德，待時而發。風為號令，若“風行天下”，則施附於物，不得雲“施未行”也。今風在天上，去物既遠，無所施及，故曰“風行天上”。凡大象，君子所取之義，或取二卦之象而法之者，若“地中有水，師，君子以容民畜眾”，取卦象包容之義；若《履卦·象》雲“上天下澤，履，君子以辯上下”，取上下尊卑之義。如此之類，皆取二象，君子法以為行也。或直取卦名，因其卦義所有，君子法之，須合卦義行事者。若《訟卦》雲“君子以作事謀始”，防其所訟之源，不取“天與水違行”之象；若《小畜》“君子以懿文德”，不取“風行天上”之象。餘皆仿此。</p><h2 id="初九-復自道-何其咎-吉。-​" tabindex="-1">初九：復自道，何其咎？吉。 ​ <a class="header-anchor" href="#初九-復自道-何其咎-吉。-​" aria-label="Permalink to “初九：復自道，何其咎？吉。 ​”">​</a></h2><p>王弼：處乾之始，以升巽初，四為已應，不距已者也。以陽升陰，復自其道，順而無違，何所犯咎，得義之吉。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：處乾之始以升巽，初四為已應，以陽升陰，反覆於上，自用已道，四則順而無違，於已無咎，故云“復自道，何其咎？吉”。</p><h3 id="《象》曰-復自道-其義吉也。-​" tabindex="-1">《象》曰：“復自道”，其義吉也。 ​ <a class="header-anchor" href="#《象》曰-復自道-其義吉也。-​" aria-label="Permalink to “《象》曰：“復自道”，其義吉也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“其義吉”者，以陽升陰，以剛應柔，其義於理吉也。</p><h2 id="九二-牽復吉。-​" tabindex="-1">九二：牽復吉。 ​ <a class="header-anchor" href="#九二-牽復吉。-​" aria-label="Permalink to “九二：牽復吉。 ​”">​</a></h2><p>王弼：處乾之中，以升巽五，五非畜極，非固已者也。雖不能若陰之不違，可牽以獲復，是以吉也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“牽”謂牽連，“復”謂反覆，二欲往五，五非止畜之極，不閉固於已，可自牽連反覆於上而得吉也。</p><h3 id="《象》曰-牽復-在中-亦不自失也。-​" tabindex="-1">《象》曰：“牽復”在中，亦不自失也。 ​ <a class="header-anchor" href="#《象》曰-牽復-在中-亦不自失也。-​" aria-label="Permalink to “《象》曰：“牽復”在中，亦不自失也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：既彊牽連，而覆在下卦之中，以其得中，不被閉固，亦於已不自有失，解“牽復吉”也。</p><h2 id="九三-輿說輻。夫妻反目。-​" tabindex="-1">九三：輿說輻。夫妻反目。 ​ <a class="header-anchor" href="#九三-輿說輻。夫妻反目。-​" aria-label="Permalink to “九三：輿說輻。夫妻反目。 ​”">​</a></h2><p>王弼：上為畜盛，不可牽徵，以斯而進，故必“說輻”也。已為陽極，上為陰長，畜於陰長，不能自復，方之“夫妻反目”之義也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：九三欲復而進，上九固而止之，不可以行，故車輿說其輻。“夫妻反目”者，上九體巽為長女之陰，今九三之陽，被長女閉固，不能自復，夫妻乖戾，故反目相視。</p><h3 id="《象》曰-夫妻反目-不能正室也。-​" tabindex="-1">《象》曰：“夫妻反目”，不能正室也。 ​ <a class="header-anchor" href="#《象》曰-夫妻反目-不能正室也。-​" aria-label="Permalink to “《象》曰：“夫妻反目”，不能正室也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“不能正室”者，釋“夫妻反目”之義。以九三之夫不能正上九之室，故“反目”也。此假象以喻人事也。</p><h2 id="六四-有孚-血去惕出-無咎。-​" tabindex="-1">六四：有孚，血去惕出，無咎。 ​ <a class="header-anchor" href="#六四-有孚-血去惕出-無咎。-​" aria-label="Permalink to “六四：有孚，血去惕出，無咎。 ​”">​</a></h2><p>王弼：夫言“血”者，陽犯陰也。四乘於三，近不相得，三務於進，而已隔之，將懼侵克者也。上亦惡三而能制焉，志與上合，共同斯誠，三雖逼己，而不能犯，故得血去懼除，保無咎也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“六四”至“無咎”。○正義曰：六四居九三之上，乘陵於三，三既務進，而已固之，懼三害己，故有“血”也。畏三侵陵，故惕懼也。但上九亦憎惡九三，六四與上九同志，共惡於三三不害己，己故得其血去除，其惕出散，信能血去懼除，乃得無咎。○注“夫言血者”至“無咎也”。○正義曰：“夫言血者陽犯陰也”者，謂此卦言“血”，陽犯陰也。“夫”者，發語之端，非是總凡之辭。故《需》六四雲“需於血”，《注》雲：“凡稱血者，陰陽相傷也”。則稱血者，非唯陽犯陰也。</p><h3 id="《象》曰-有孚惕出-上合志也。-​" tabindex="-1">《象》曰：有孚惕出，上合志也。 ​ <a class="header-anchor" href="#《象》曰-有孚惕出-上合志也。-​" aria-label="Permalink to “《象》曰：有孚惕出，上合志也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋“惕出”之意。所以“惕出”者，由己與上九同合其志，共惡於三也。</p><h2 id="九五-有孚攣如-富以其鄰。-​" tabindex="-1">九五：有孚攣如，富以其鄰。 ​ <a class="header-anchor" href="#九五-有孚攣如-富以其鄰。-​" aria-label="Permalink to “九五：有孚攣如，富以其鄰。 ​”">​</a></h2><p>王弼：處得尊位，不疑於二，來而不距。二牽已攣，不為專固，“有孚攣如”之謂也。以陽居陽，處實者也。居盛處實而不專固，富以其鄰者也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“有孚攣如”者，五居尊位，不疑於二，來而不距。二既牽挽而來，已又攀攣而迎接，志意合同，不有專固相逼，是有信而相牽攣也。“如”，語辭，非義類。“富以其鄰”者，五是陽爻，即必富實。心不專固，故能用富以與其鄰。“鄰”謂二也。</p><h3 id="《象》曰-有孚攣如-不獨富也。-​" tabindex="-1">《象》曰：“有孚攣如”，不獨富也。 ​ <a class="header-anchor" href="#《象》曰-有孚攣如-不獨富也。-​" aria-label="Permalink to “《象》曰：“有孚攣如”，不獨富也。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“不獨富也”者，釋“攣如”之義。所以攀攣於二者，以其不獨自專固於富，欲分與二也。</p><h2 id="上九-既雨既處-尚德載-婦貞厲-月幾望-君子徵兇。-​" tabindex="-1">上九：既雨既處，尚德載，婦貞厲，月幾望，君子徵兇。 ​ <a class="header-anchor" href="#上九-既雨既處-尚德載-婦貞厲-月幾望-君子徵兇。-​" aria-label="Permalink to “上九：既雨既處，尚德載，婦貞厲，月幾望，君子徵兇。 ​”">​</a></h2><p>王弼：處小畜之極，能畜者也。陽不獲亨，故“既雨”也。剛不能侵，故“既處”也。體《巽》處上，剛不敢犯，“尚德”者也。為陰之長，能畜剛健，德積載者也。婦制其夫，臣制其君，雖貞近危，故曰“婦貞厲”也。陰之盈盛莫盛於此，故曰“月幾望”也。滿而又進，必失其道，陰疑於陽，必見戰伐，雖復君子，以徵必兇，故曰“君子徵兇”。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“上九，既雨既處”至“君子徵兇”。○正義曰：“既雨既處”者，九三欲進，已能固之，陰陽不通，故已得其雨也。“既處”者，三不能侵，不憂危害，故已得其處也。“尚德載”者，體《巽》處上，剛不敢犯，為陰之長，能畜正剛健，慕尚此德之積聚而運載也，故云“尚德載”也。言慕尚此道德之積載也。“婦貞厲”者，上九制九三，是婦制其夫，臣制其君，雖復貞正，而近危厲也。“月幾望”者，婦人之制夫，猶如月在望時盛極以敵日也。“幾”，辭也，已從上釋，故於此不復言也。“君子徵兇”者，陰疑於陽，必見戰伐，雖復君子之行而亦兇也。○注“處小畜之極”至“君子徵兇”。○正義曰：“處小畜之極，能畜者也”者。已處小畜盛極，是閉畜者也。“陽不獲亨，故既雨也”者，陽若亨通則不雨也。所以卦繫辭雲：“小畜，亨，密雲不雨。”今九三之陽，被上九所固，不獲亨通，故“既雨”也。</p><h3 id="《象》曰-既雨既處-德積載也。-君子徵兇-有所疑也。-​" tabindex="-1">《象》曰：“既雨既處”，德積載也。“君子徵兇”，有所疑也。 ​ <a class="header-anchor" href="#《象》曰-既雨既處-德積載也。-君子徵兇-有所疑也。-​" aria-label="Permalink to “《象》曰：“既雨既處”，德積載也。“君子徵兇”，有所疑也。 ​”">​</a></h3><p>王弼：夫處下可以徵而無咎者，唯泰也則然。坤本體下，又順而弱，不能敵剛，故可以全其類，徵而吉也。自此以往，則其進各有難矣。夫巽雖不能若艮之善畜，猶不肯為坤之順從也，故可得少進，不可盡陵也。是以初九、九二，其復則可，至於九三，則“輿說輻”也。夫大畜者，畜之極也。畜而不已，畜極則通，是以其畜之盛在於四、五，至於上九，道乃大行。小畜積極而後乃能畜，是以四、五可以進，而上九說徵之輻。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰既雨既處”至“有所疑也”。</p><p>○正義曰：“既雨既處，德積載”者，釋“既雨既處”之義。言所以得“既雨既處”者，以上九道德積聚，可以運載，使人慕尚，故云“既雨既處”也。“君子徵兇有所疑”者，釋“君子徵兇”之義，言所以“徵兇”者，陰氣盛滿，被陽有所疑忌，必見戰伐，故“徵兇”也。</p><p>○注“夫處下”至“說徵之輻”。</p><p>○正義曰：“夫巽雖不能若艮之善畜”者，謂雖不能如大畜艮卦在上，善畜下之乾也。“巽雖不能如艮之善畜”，故其畜小也。“猶不肯為坤之順從”者，謂猶不肯如泰卦、坤在於上順從乾也。“故可得少進”者，謂初九、九二得前進也。“不可盡陵”者，九三欲陵上九，被上九所固，是不可得“盡陵”也。“畜而不已，畜極則通，是以其畜之盛在於四五，至於上九，道乃大行”者，此論大畜義也。大畜畜而不已，謂之“大畜”。四爻、五爻是畜之盛極，而不休已，畜極則通。四、五畜道既極，至於上九，無可所畜，故上九道乃大行，無所畜也。“小畜積極而後乃能畜”者，小畜之道既微，積其終極，至於上九，乃能畜也，謂“畜”九三也。“是以四、五可以進”者，四雖畜初，五雖畜二，畜道既弱，故九二可以進。“上九說徵之輻”者，上九畜之“積極”，故能說此九三徵行之輻。案：九三但有“說輻”，無“徵”之文。而王氏言上九“說徵之輻”者，輿之有輻，可以徵行。九三爻有“徵”義，今輿輻既說，則是說徵之輻，因上九“徵兇”之文，徵則行也。文雖不言，於義必有言“輻”者，鄭《注》雲“謂輿下縛木，與軸相連，鉤心之木”是也。《子夏傳》雲：“輻，車劇也。”</p>',71)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
